def roles_vers_groupes(apps, schema_editor):
    """Cree les groupes par defaut et y affecte les utilisateurs selon
    leur ancien role."""
    from apps.commun.constantes import GROUPES_PAR_DEFAUT

    Groupe = apps.get_model("utilisateurs", "Groupe")
    Utilisateur = apps.get_model("utilisateurs", "Utilisateur")
    for nom, definition in GROUPES_PAR_DEFAUT.items():
        Groupe.objects.get_or_create(nom=nom, defaults={
            "description": definition["description"],
            "acces_total": definition["permissions"] is None,
            "permissions": definition["permissions"] or [],
        })
    for role, nom in ROLES.items():
        Utilisateur.objects.filter(role=role).update(groupe=Groupe.objects.get(nom=nom))


